// ------------------------------------------------------------ результаты замеров (db/perf/results.md)
const fmt = (x, d = 1) => {
  const [i, f] = Number(x).toFixed(d).split(".");
  const ii = i.replace(/\B(?=(\d{3})+(?!\d))/g, " ");
  return f ? `${ii},${f}` : ii;
};
const BENCH = {};
fs.readFileSync(path.join(ROOT, "db/perf/results.md"), "utf8").split("\n").forEach((l) => {
  const m = l.match(/^\| (Q\d|W\d) \| (.*?) \| ([\d.]+) \| ([\d.]+) \| ([\d.]+) \| (\d+) \| (\d+) \|$/);
  if (m) BENCH[m[1]] = { title: m[2], before: +m[3], after: +m[4], k: +m[5], bb: +m[6], ba: +m[7] };
});
const IDX_SIZE = (fs.readFileSync(path.join(ROOT, "db/perf/results.md"), "utf8").match(/их размер (\d+) MB/) || [])[1];

