add(H1("2 Проектирование системы"));
add(H2("2.1 Процессная модель"));
add(
  P("Процесс — совокупность операций и их обеспечения. Формально процессы системы описываются так:", { keepNext: true }),
);
add(formula("procs", [mr("P = {"), sub("P", "1"), mr(", …, "), sub("P", "6"), mr("},   "), sub("P", "i"), mr(" = ⟨"),
  sub("X", "i"), mr(", "), sub("Y", "i"), mr(", "), sub("Z", "i"), mr(", "), sub("O", "i"), mr(", "), sub("K", "i"), mr(", "),
  sub("R", "i"), mr(", "), sub("H", "i"), mr("⟩,")]));
add(where([
  "X_{i}, Y_{i}, Z_{i} — входные, выходные и внутренние данные процесса;",
  "O_{i}, K_{i}, R_{i} — операции, программные компоненты и информационные ресурсы;",
  "H_{i} — участие человека.",
]));
add(
  P("Для системы получаются «множества множеств» O = {O_{1}, …, O_{6}}, K = {K_{1}, …, K_{6}}, R = {R_{1}, …, R_{6}}. Состав процессов приведён в таблице {tab:procs}. Основной бизнес-процесс — выполнение задачи в созданном проекте, участники которого зарегистрированы и включены в команду. Он описан в нотации BPMN {cite:bpmn} (рисунок {fig:bpmn}) с дорожками руководителя, исполнителя, тестировщика и системы. Руководитель создаёт задачу, оценивает и назначает её и включает в спринт. Сервисная задача 4.6 проверяет ёмкость спринта; при превышении граничное событие ошибки возвращает задачу руководителю. Далее исполнитель берёт задачу в работу и передаёт на проверку, а тестировщик принимает её или возвращает с замечанием. Таймер «срок прошёл» запускает эскалацию. Сервисные задачи связаны с хранилищами D4, D5 и электронными документами: карточкой задачи и уведомлениями. Каждую смену статуса записывает в историю триггер."),
);

add(H2("2.2 Логическая модель и нормализация"));
