// ====================================================================
// ПРИЛОЖЕНИЯ
// ====================================================================
function appendix(key, status, title, pageBreak = true) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1, alignment: C_, indent: { firstLine: 0 }, pageBreakBefore: pageBreak,
    children: [
      new TextRun({ text: `ПРИЛОЖЕНИЕ ${num("app", key)}`, font: FONT, size: 28, bold: true }),
      new TextRun({ text: `(${status})`, font: FONT, size: 28, bold: false, break: 1 }),
      new TextRun({ text: title, font: FONT, size: 28, bold: true, break: 1 }),
    ],
  });
}
const lstTitle = (t) => new Paragraph({ spacing: { before: 240, after: 120, line: 240 }, keepNext: true, children: runs(t, { size: 26 }) });

