const footer = () => new Footer({ children: [new Paragraph({ alignment: C_,
  children: [new TextRun({ children: [PageNumber.CURRENT], font: FONT, size: 28 })] })] });
const emptyFooter = new Footer({ children: [new Paragraph({ children: [] })] });
const MARGIN_P = { top: 1134, bottom: 1134, left: 1701, right: 850, footer: 567, header: 567 };
const MARGIN_L = { top: 1701, bottom: 850, left: 1134, right: 1134, footer: 397, header: 567 };

const docSections = sections.map((s, i) => {
  const land = s.kind === "land";
  const props = {
    page: {
      size: { width: 11906, height: 16838, orientation: land ? PageOrientation.LANDSCAPE : PageOrientation.PORTRAIT },
      margin: land ? MARGIN_L : MARGIN_P,
    },
  };
  if (i > 0) props.type = SectionType.NEXT_PAGE;
  if (i === 0) props.titlePage = true;
  return {
    properties: props,
    footers: i === 0 ? { default: footer(), first: emptyFooter } : { default: footer() },
    children: s.children,
  };
});

const headingStyle = (o) => ({
  run: { font: FONT, size: 28, bold: true, color: "000000" },
  paragraph: { spacing: { before: o.before, after: o.after, line: 360 }, keepNext: true, keepLines: true,
    indent: { firstLine: INDENT }, alignment: AlignmentType.LEFT },
});
const doc = new Document({
  creator: "", title: "Пояснительная записка — Система управления проектами",
  styles: {
    default: {
      document: { run: { font: FONT, size: 28 }, paragraph: { spacing: { line: 360 } } },
      heading1: headingStyle({ before: 0, after: 360 }),
      heading2: headingStyle({ before: 360, after: 240 }),
      heading3: headingStyle({ before: 240, after: 120 }),
    },
    paragraphStyles: [
      { id: "TOC1", name: "toc 1", basedOn: "Normal", next: "Normal", run: { font: FONT, size: 28 },
        paragraph: { spacing: { before: 0, after: 0, line: 360 }, indent: { left: 0 } } },
      { id: "TOC2", name: "toc 2", basedOn: "Normal", next: "Normal", run: { font: FONT, size: 28 },
        paragraph: { spacing: { before: 0, after: 0, line: 360 }, indent: { left: 280 } } },
    ],
  },
  numbering: { config: numberingConfig },
  sections: docSections,
});

const out = process.argv[2] || path.join(__dirname, "note_short.docx");
Packer.toBuffer(doc).then((buf) => {
  fs.writeFileSync(out, buf);
  const stats = {
    figs: counters.fig.length + Object.keys(appItems.fig).length,
    tabs: counters.tab.length + Object.keys(appItems.tab).length,
    srcs: counters.cite.length, apps: counters.app.length,
  };
  fs.writeFileSync(path.join(__dirname, "counts_short.json"), JSON.stringify(stats));
  console.log("ok", out, JSON.stringify(stats));
});
